// --- doc.FDb._db.ReadArgv
// Read argc,argv into the fields of doc.FDb.cmdline (and any base command line)
// via doc_ReadArgv; then apply -help/-version and load floadtuples input.
void doc::ReadArgv() {
    command::doc &cmd = doc::_db.cmdline;
    algo::cstring err;
    algo::StringAry args;
    for (int argidx=1; argidx < algo_lib::_db.argc; argidx++) {// skip process name
        ary_Alloc(args) = algo_lib::_db.argv[argidx];
    }
    command::doc_ReadArgv(cmd, args, err);
    bool dohelp = false;
    bool doexit=false;
    if (algo_lib::_db.cmdline.help) {
        dohelp = true;
        doexit = true;
        algo_lib::_db.exit_code = 1; // help exits with non-zero status code
    } else if (algo_lib::_db.cmdline.version) {
        // -ver output goes to stdout
        prlog(algo::gitinfo_Get());
        doexit = true;
    } else if (algo_lib::_db.cmdline.signature) {
        ind_beg(algo_lib::_db_dispsigcheck_curs,dispsigcheck,algo_lib::_db) {
            // dispsig goes to stdout
            dmmeta::Dispsigcheck out;
            dispsigcheck_CopyOut(dispsigcheck,out);
            prlog(out);
        }ind_end
        doexit = true;
    }
    algo_lib_logcat_debug.enabled = algo_lib::_db.cmdline.debug;
    algo_lib_logcat_verbose.enabled = algo_lib::_db.cmdline.verbose > 0;
    algo_lib_logcat_verbose2.enabled = algo_lib::_db.cmdline.verbose > 1;
    // dmmeta.floadtuples:command.doc.in
    if (!dohelp && err=="") {
        algo_lib::ResetErrtext();
        if (!doc::LoadTuplesMaybe(cmd.in,true)) {
            err << "doc.load_input  "<<algo_lib::DetachBadTags()<<eol;
        }
    }
    if (err != "") {
        algo_lib::_db.exit_code=1;
        prerr_(err); // already has eol
        doexit=true;
    }
    if (dohelp) {
        prlog(command::doc_help);
    }
    if (doexit) {
        _exit(algo_lib::_db.exit_code);
    }
    algo_lib::ResetErrtext();
}

// --- doc.FDb._db.MainLoop
// Main loop.
void doc::MainLoop() {
    algo::SchedTime time(algo::get_cycles());
    algo_lib::_db.clock          = time;
    do {
        algo_lib::_db.next_loop.value = algo_lib::_db.limit;
        doc::Steps();
    } while (algo_lib::_db.next_loop < algo_lib::_db.limit);
}

