// --- doc.FDb._db.LoadTuplesMaybe
// Load all finputs from given directory.
bool doc::LoadTuplesMaybe(algo::strptr root, bool recursive) {
    bool retval = true;
    if (FileQ(root)) {
        retval = doc::LoadTuplesFile(root, recursive);
    } else if (root == "-") {
        retval = doc::LoadTuplesFd(algo::Fildes(0),"(stdin)",recursive);
    } else if (DirectoryQ(root)) {
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.ns"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.ctype"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.field"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.typefld"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.ssimfile"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.msgtype"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.msg"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.msgfield"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.gstatic"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.finput"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.fconst"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.dispatch"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.dispsigcheck"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dmmeta.dispatch_msg"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dev.gitfile"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dev.targsrc"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dev.targdep"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"dev.readmefile"),recursive);
        retval = retval && doc::LoadTuplesFile(algo::SsimFname(root,"atfdb.comptest"),recursive);
    } else {
        algo_lib::AppendErrtext("path", root);
        algo_lib::AppendErrtext("comment", "Wrong working directory?");
        retval = false;
    }
    return retval;
}

// --- doc.FDb._db.LoadTuplesFile
// Load all finputs from given file.
// Read tuples from file FNAME into this namespace's in-memory database.
// If RECURSIVE is TRUE, then also load these tuples into any parent namespaces
// It a file referred to by FNAME is missing, no error is reported (it's considered an empty set).
// Function returns TRUE if all records were parsed and inserted without error.
// If the function returns FALSE, use algo_lib::DetachBadTags() for error description
bool doc::LoadTuplesFile(algo::strptr fname, bool recursive) {
    bool retval = true;
    algo_lib::FFildes fildes;
    // missing files are not an error
    fildes.fd = OpenRead(fname,algo::FileFlags());
    if (ValidQ(fildes.fd)) {
        retval = LoadTuplesFd(fildes.fd, fname, recursive);
    }
    return retval;
}

// --- doc.FDb._db.LoadTuplesFd
// Load all finputs from given file descriptor.
bool doc::LoadTuplesFd(algo::Fildes fd, algo::strptr fname, bool recursive) {
    bool retval = true;
    ind_beg(algo::FileLine_curs,line,fd) {
        if (recursive) {
            retval = retval && algo_lib::InsertStrptrMaybe(line);
        }
        retval = retval && doc::InsertStrptrMaybe(line);
        if (!retval) {
            algo_lib::_db.errtext << eol
            << fname << ":"
            << (ind_curs(line).i+1)
            << ": " << line << eol;
            break;
        }
    }ind_end;
    return retval;
}

// --- doc.FDb._db.LoadSsimfileMaybe
// Load specified ssimfile.
bool doc::LoadSsimfileMaybe(algo::strptr fname, bool recursive) {
    bool retval = true;
    if (FileQ(fname)) {
        retval = doc::LoadTuplesFile(fname, recursive);
    }
    return retval;
}

