// Find row by key. Return NULL if not found.
doc::FReadmefile* doc::ind_readmefile_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr200_Hash(0, key) & (_db.ind_readmefile_buckets_n - 1);
    doc::FReadmefile *ret = _db.ind_readmefile_buckets_elems[index];
    for (; ret && !((*ret).gitfile == key); ret = ret->ind_readmefile_next) {
    }
    return ret;
}

// --- doc.FDb.ind_readmefile.FindX
// Look up row by key and return reference. Throw exception if not found
doc::FReadmefile& doc::ind_readmefile_FindX(const algo::strptr& key) {
    doc::FReadmefile* ret = ind_readmefile_Find(key);
    vrfy(ret, tempstr() << "doc.key_error  table:ind_readmefile  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- doc.FDb.ind_readmefile.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
doc::FReadmefile& doc::ind_readmefile_GetOrCreate(const algo::strptr& key) {
    doc::FReadmefile* ret = ind_readmefile_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &readmefile_Alloc();
        (*ret).gitfile = key;
        bool good = readmefile_XrefMaybe(*ret);
        if (!good) {
            readmefile_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "doc.create_error  table:ind_readmefile  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- doc.FDb.ind_readmefile.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool doc::ind_readmefile_InsertMaybe(doc::FReadmefile& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_readmefile_next == (doc::FReadmefile*)-1)) {// check if in hash already
        row.ind_readmefile_hashval = algo::Smallstr200_Hash(0, row.gitfile);
        ind_readmefile_Reserve(1);
        u32 index = row.ind_readmefile_hashval & (_db.ind_readmefile_buckets_n - 1);
        doc::FReadmefile* *prev = &_db.ind_readmefile_buckets_elems[index];
        do {
            doc::FReadmefile* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).gitfile == row.gitfile) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_readmefile_next;
        } while (true);
        if (retval) {
            row.ind_readmefile_next = *prev;
            _db.ind_readmefile_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- doc.FDb.ind_readmefile.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void doc::ind_readmefile_Remove(doc::FReadmefile& row) {
    if (LIKELY(row.ind_readmefile_next != (doc::FReadmefile*)-1)) {// check if in hash already
        u32 index = row.ind_readmefile_hashval & (_db.ind_readmefile_buckets_n - 1);
        doc::FReadmefile* *prev = &_db.ind_readmefile_buckets_elems[index]; // addr of pointer to current element
        while (doc::FReadmefile *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_readmefile_next; // unlink (singly linked list)
                _db.ind_readmefile_n--;
                row.ind_readmefile_next = (doc::FReadmefile*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_readmefile_next;
        }
    }
}

// --- doc.FDb.ind_readmefile.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void doc::ind_readmefile_Reserve(int n) {
    ind_readmefile_AbsReserve(_db.ind_readmefile_n + n);
}

// --- doc.FDb.ind_readmefile.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void doc::ind_readmefile_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_readmefile_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(doc::FReadmefile*);
        u32 new_size = new_nbuckets * sizeof(doc::FReadmefile*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        doc::FReadmefile* *new_buckets = (doc::FReadmefile**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("doc.out_of_memory  field:doc.FDb.ind_readmefile");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_readmefile_buckets_n; i++) {
            doc::FReadmefile* elem = _db.ind_readmefile_buckets_elems[i];
            while (elem) {
                doc::FReadmefile &row        = *elem;
                doc::FReadmefile* next       = row.ind_readmefile_next;
                u32 index          = row.ind_readmefile_hashval & (new_nbuckets-1);
                row.ind_readmefile_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_readmefile_buckets_elems, old_size);
        _db.ind_readmefile_buckets_elems = new_buckets;
        _db.ind_readmefile_buckets_n = new_nbuckets;
    }
}

// --- doc.FDb.block.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
doc::FBlock& doc::block_Alloc() {
    doc::FBlock* row = block_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("doc.out_of_mem  field:doc.FDb.block  comment:'Alloc failed'");
    }
    return *row;
}

// --- doc.FDb.block.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
doc::FBlock* doc::block_AllocMaybe() {
    doc::FBlock *row = (doc::FBlock*)block_AllocMem();
    if (row) {
        new (row) doc::FBlock; // call constructor
    }
    return row;
}

// --- doc.FDb.block.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* doc::block_AllocMem() {
    u64 new_nelems     = _db.block_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    doc::FBlock*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.block_lary[bsr];
        if (!lev) {
            lev=(doc::FBlock*)algo_lib::malloc_AllocMem(sizeof(doc::FBlock) * (u64(1)<<bsr));
            _db.block_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.block_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- doc.FDb.block.RemoveAll
// Remove all elements from Lary
void doc::block_RemoveAll() {
    for (u64 n = _db.block_n; n>0; ) {
        n--;
        block_qFind(u64(n)).~FBlock(); // destroy last element
        _db.block_n = i64(n);
    }
}

// --- doc.FDb.block.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void doc::block_RemoveLast() {
    u64 n = _db.block_n;
    if (n > 0) {
        n -= 1;
        block_qFind(u64(n)).~FBlock();
        _db.block_n = i64(n);
    }
}

