// --- doc.FDb.cell.Insary
// Insert array at specific position
// Insert N elements at specified index. Index must be in range or a fatal error occurs.Reserve space, and move existing elements to end.If the RHS argument aliases the array (refers to the same memory), exit program with fatal error.
void doc::cell_Insary(algo::aryptr<doc::Cell> rhs, i64 at) {
    bool overlaps = rhs.n_elems>0 && rhs.elems >= _db.cell_elems && rhs.elems < _db.cell_elems + _db.cell_max;
    if (UNLIKELY(overlaps)) {
        FatalErrorExit("doc.tary_alias  field:doc.FDb.cell  comment:'alias error: sub-array is being appended to the whole'");
    }
    if (UNLIKELY(u64(at) >= u64(_db.cell_n+1))) {
        FatalErrorExit("doc.bad_insary  field:doc.FDb.cell  comment:'index out of range'");
    }
    i64 nnew = rhs.n_elems;
    i64 nmove = _db.cell_n - at;
    cell_Reserve(nnew); // reserve space
    for (i64 i = nmove-1; i >=0 ; --i) {
        new (_db.cell_elems + at + nnew + i) doc::Cell(_db.cell_elems[at + i]);
    }
    for (i64 i = 0; i < nnew; ++i) {
        new (_db.cell_elems + at + i) doc::Cell(rhs[i]);
    }
    _db.cell_n += nnew;
}

// --- doc.FDb.cell.RemRegion
// Delete a range of elements
// Remove region from the middle of the array
// The specified region BEG..BEG+N is clipped to the valid region both from the left and from the right.
// If N is negative, nothing is removed.
void doc::cell_RemRegion(i64 beg, i64 n) {
    i64 end = i64_Min(beg+n, _db.cell_n);
    beg = i64_Max(beg,0);
    n = end-beg;
    if (n>0) {
        memmove(_db.cell_elems+beg, _db.cell_elems+end, sizeof(doc::Cell) * (_db.cell_n-end));
        _db.cell_n -= n;
    }
}

