        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "doc.duplicate_key  xref:doc.FDb.ind_ssimfile_ctype"; // check for duplicate key
            return false;
        }
