// --- doc.FDb.ind_ssimfile_ctype.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool doc::ind_ssimfile_ctype_InsertMaybe(doc::FSsimfile& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_ssimfile_ctype_next == (doc::FSsimfile*)-1)) {// check if in hash already
        row.ind_ssimfile_ctype_hashval = algo::Smallstr100_Hash(0, row.ctype);
        ind_ssimfile_ctype_Reserve(1);
        u32 index = row.ind_ssimfile_ctype_hashval & (_db.ind_ssimfile_ctype_buckets_n - 1);
        doc::FSsimfile* *prev = &_db.ind_ssimfile_ctype_buckets_elems[index];
        do {
            doc::FSsimfile* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).ctype == row.ctype) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_ssimfile_ctype_next;
        } while (true);
        if (retval) {
            row.ind_ssimfile_ctype_next = *prev;
            _db.ind_ssimfile_ctype_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- doc.FDb.ind_ssimfile_ctype.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void doc::ind_ssimfile_ctype_Remove(doc::FSsimfile& row) {
    if (LIKELY(row.ind_ssimfile_ctype_next != (doc::FSsimfile*)-1)) {// check if in hash already
        u32 index = row.ind_ssimfile_ctype_hashval & (_db.ind_ssimfile_ctype_buckets_n - 1);
        doc::FSsimfile* *prev = &_db.ind_ssimfile_ctype_buckets_elems[index]; // addr of pointer to current element
        while (doc::FSsimfile *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_ssimfile_ctype_next; // unlink (singly linked list)
                _db.ind_ssimfile_ctype_n--;
                row.ind_ssimfile_ctype_next = (doc::FSsimfile*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_ssimfile_ctype_next;
        }
    }
}

