// --- doc.FDb.ind_docpage.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool doc::ind_docpage_InsertMaybe(doc::FDocpage& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_docpage_next == (doc::FDocpage*)-1)) {// check if in hash already
        row.ind_docpage_hashval = algo::Smallstr50_Hash(0, row.docpage);
        ind_docpage_Reserve(1);
        u32 index = row.ind_docpage_hashval & (_db.ind_docpage_buckets_n - 1);
        doc::FDocpage* *prev = &_db.ind_docpage_buckets_elems[index];
        do {
            doc::FDocpage* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).docpage == row.docpage) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_docpage_next;
        } while (true);
        if (retval) {
            row.ind_docpage_next = *prev;
            _db.ind_docpage_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- doc.FDb.ind_docpage.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void doc::ind_docpage_Remove(doc::FDocpage& row) {
    if (LIKELY(row.ind_docpage_next != (doc::FDocpage*)-1)) {// check if in hash already
        u32 index = row.ind_docpage_hashval & (_db.ind_docpage_buckets_n - 1);
        doc::FDocpage* *prev = &_db.ind_docpage_buckets_elems[index]; // addr of pointer to current element
        while (doc::FDocpage *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_docpage_next; // unlink (singly linked list)
                _db.ind_docpage_n--;
                row.ind_docpage_next = (doc::FDocpage*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_docpage_next;
        }
    }
}

// --- doc.FDb.ind_docpage.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void doc::ind_docpage_Reserve(int n) {
    ind_docpage_AbsReserve(_db.ind_docpage_n + n);
}

// --- doc.FDb.ind_docpage.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void doc::ind_docpage_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_docpage_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(doc::FDocpage*);
        u32 new_size = new_nbuckets * sizeof(doc::FDocpage*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        doc::FDocpage* *new_buckets = (doc::FDocpage**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("doc.out_of_memory  field:doc.FDb.ind_docpage");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_docpage_buckets_n; i++) {
            doc::FDocpage* elem = _db.ind_docpage_buckets_elems[i];
            while (elem) {
                doc::FDocpage &row        = *elem;
                doc::FDocpage* next       = row.ind_docpage_next;
                u32 index          = row.ind_docpage_hashval & (new_nbuckets-1);
                row.ind_docpage_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_docpage_buckets_elems, old_size);
        _db.ind_docpage_buckets_elems = new_buckets;
        _db.ind_docpage_buckets_n = new_nbuckets;
    }
}

