// --- doc.FDb.gstatic.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
doc::FGstatic* doc::gstatic_AllocMaybe() {
    doc::FGstatic *row = (doc::FGstatic*)gstatic_AllocMem();
    if (row) {
        new (row) doc::FGstatic; // call constructor
    }
    return row;
}

// --- doc.FDb.gstatic.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
doc::FGstatic* doc::gstatic_InsertMaybe(const dmmeta::Gstatic &value) {
    doc::FGstatic *row = &gstatic_Alloc(); // if out of memory, process dies. if input error, return NULL.
    gstatic_CopyIn(*row,const_cast<dmmeta::Gstatic&>(value));
    bool ok = gstatic_XrefMaybe(*row); // this may return false
    if (!ok) {
        gstatic_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- doc.FDb.gstatic.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* doc::gstatic_AllocMem() {
    u64 new_nelems     = _db.gstatic_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    doc::FGstatic*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.gstatic_lary[bsr];
        if (!lev) {
            lev=(doc::FGstatic*)algo_lib::malloc_AllocMem(sizeof(doc::FGstatic) * (u64(1)<<bsr));
            _db.gstatic_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.gstatic_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- doc.FDb.gstatic.RemoveAll
// Remove all elements from Lary
void doc::gstatic_RemoveAll() {
    for (u64 n = _db.gstatic_n; n>0; ) {
        n--;
        gstatic_qFind(u64(n)).~FGstatic(); // destroy last element
        _db.gstatic_n = i64(n);
    }
}

// --- doc.FDb.gstatic.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void doc::gstatic_RemoveLast() {
    u64 n = _db.gstatic_n;
    if (n > 0) {
        n -= 1;
        gstatic_qFind(u64(n)).~FGstatic();
        _db.gstatic_n = i64(n);
    }
}

