// --- doc.FDb.typefld.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
doc::FTypefld* doc::typefld_InsertMaybe(const dmmeta::Typefld &value) {
    doc::FTypefld *row = &typefld_Alloc(); // if out of memory, process dies. if input error, return NULL.
    typefld_CopyIn(*row,const_cast<dmmeta::Typefld&>(value));
    bool ok = typefld_XrefMaybe(*row); // this may return false
    if (!ok) {
        typefld_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- doc.FDb.typefld.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* doc::typefld_AllocMem() {
    u64 new_nelems     = _db.typefld_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    doc::FTypefld*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.typefld_lary[bsr];
        if (!lev) {
            lev=(doc::FTypefld*)algo_lib::malloc_AllocMem(sizeof(doc::FTypefld) * (u64(1)<<bsr));
            _db.typefld_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.typefld_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- doc.FDb.typefld.RemoveAll
// Remove all elements from Lary
void doc::typefld_RemoveAll() {
    for (u64 n = _db.typefld_n; n>0; ) {
        n--;
        typefld_qFind(u64(n)).~FTypefld(); // destroy last element
        _db.typefld_n = i64(n);
    }
}

// --- doc.FDb.typefld.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void doc::typefld_RemoveLast() {
    u64 n = _db.typefld_n;
    if (n > 0) {
        n -= 1;
        typefld_qFind(u64(n)).~FTypefld();
        _db.typefld_n = i64(n);
    }
}

