// --- doc.FDb.ind_msgtype.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool doc::ind_msgtype_InsertMaybe(doc::FMsgtype& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_msgtype_next == (doc::FMsgtype*)-1)) {// check if in hash already
        row.ind_msgtype_hashval = algo::Smallstr100_Hash(0, row.ctype);
        ind_msgtype_Reserve(1);
        u32 index = row.ind_msgtype_hashval & (_db.ind_msgtype_buckets_n - 1);
        doc::FMsgtype* *prev = &_db.ind_msgtype_buckets_elems[index];
        do {
            doc::FMsgtype* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).ctype == row.ctype) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_msgtype_next;
        } while (true);
        if (retval) {
            row.ind_msgtype_next = *prev;
            _db.ind_msgtype_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- doc.FDb.ind_msgtype.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void doc::ind_msgtype_Remove(doc::FMsgtype& row) {
    if (LIKELY(row.ind_msgtype_next != (doc::FMsgtype*)-1)) {// check if in hash already
        u32 index = row.ind_msgtype_hashval & (_db.ind_msgtype_buckets_n - 1);
        doc::FMsgtype* *prev = &_db.ind_msgtype_buckets_elems[index]; // addr of pointer to current element
        while (doc::FMsgtype *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_msgtype_next; // unlink (singly linked list)
                _db.ind_msgtype_n--;
                row.ind_msgtype_next = (doc::FMsgtype*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_msgtype_next;
        }
    }
}

