// --- doc.FDb..Uninit
void doc::FDb_Uninit() {

    // doc.FDb.ind_msg.Uninit (Thash)  //
    // skip destruction of ind_msg in global scope

    // doc.FDb.msgfield.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.msg.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.ind_dispatch.Uninit (Thash)  //
    // skip destruction of ind_dispatch in global scope

    // doc.FDb.ind_msgtype.Uninit (Thash)  //
    // skip destruction of ind_msgtype in global scope

    // doc.FDb.msgtype.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.typefld.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.ind_readmedir.Uninit (Thash)  //Directories by path, so a code span naming one can be recognized
    // skip destruction of ind_readmedir in global scope

    // doc.FDb.readmedir.Uninit (Lary)  //Every directory dev.readmefile names, each once
    // skip destruction in global scope

    // doc.FDb.dispatch_msg.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.dispatch.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.gstatic.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.ind_docpage.Uninit (Thash)  //Pages doc generates, by name
    // skip destruction of ind_docpage in global scope

    // doc.FDb.docpage.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.span.Uninit (Lary)  //Spans of the inline text now being emitted
    // skip destruction in global scope

    // doc.FDb.fconst.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.comptest.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.finput.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.targdep.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.targsrc.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.ind_gitfile.Uninit (Thash)  //
    // skip destruction of ind_gitfile in global scope

    // doc.FDb.gitfile.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.ind_ns.Uninit (Thash)  //
    // skip destruction of ind_ns in global scope

    // doc.FDb.ns.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.ind_subject.Uninit (Thash)  //Subjects by name, so a page names each of them once
    // skip destruction of ind_subject in global scope

    // doc.FDb.subject.Uninit (Lary)  //What the query page is about, in the order the records named it
    // skip destruction in global scope

    // doc.FDb.ind_ctype.Uninit (Thash)  //
    // skip destruction of ind_ctype in global scope

    // doc.FDb.ctype.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.screenrow.Uninit (Lary)  //The screen as it stands, one record per display line
    // skip destruction in global scope

    // doc.FDb.ind_ssimfile_ctype.Uninit (Thash)  //
    // skip destruction of ind_ssimfile_ctype in global scope

    // doc.FDb.ind_field.Uninit (Thash)  //
    // skip destruction of ind_field in global scope

    // doc.FDb.field.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.ind_ssimfile.Uninit (Thash)  //
    // skip destruction of ind_ssimfile in global scope

    // doc.FDb.ssimfile.Uninit (Lary)  //
    // skip destruction in global scope

    // doc.FDb.anchor.Uninit (Lary)  //Heading anchors of the page, in document order
    // skip destruction in global scope

    // doc.FDb.hist.Uninit (Lary)  //Where the reader has been, most recent last
    // skip destruction in global scope

    // doc.FDb.run.Uninit (Lary)  //Runs rendered for the block being laid out
    // skip destruction in global scope

    // doc.FDb.link.Uninit (Lary)  //Followable links of the page, in document order
    // skip destruction in global scope

    // doc.FDb.row.Uninit (Tary)  //Where each rasterized row begins and how long it is
    // remove all elements from doc.FDb.row
    row_RemoveAll();
    // free memory for Tary doc.FDb.row
    algo_lib::malloc_FreeMem(_db.row_elems, sizeof(doc::Row)*_db.row_max); // (doc.FDb.row)

    // doc.FDb.cell.Uninit (Tary)  //Every rasterized cell of the page, rows laid end to end
    // remove all elements from doc.FDb.cell
    cell_RemoveAll();
    // free memory for Tary doc.FDb.cell
    algo_lib::malloc_FreeMem(_db.cell_elems, sizeof(doc::Cell)*_db.cell_max); // (doc.FDb.cell)

    // doc.FDb.c_match.Uninit (Ptrary)  //Documents the key resolved to
    algo_lib::malloc_FreeMem(_db.c_match_elems, sizeof(doc::FReadmefile*)*_db.c_match_max); // (doc.FDb.c_match)

    // doc.FDb.block.Uninit (Lary)  //Parsed blocks of the current document, in order
    // skip destruction in global scope

    // doc.FDb.ind_readmefile.Uninit (Thash)  //
    // skip destruction of ind_readmefile in global scope

    // doc.FDb.readmefile.Uninit (Lary)  //
    // skip destruction in global scope
}

// --- doc.FDispatch.base.CopyOut
// Copy fields out of row
void doc::dispatch_CopyOut(doc::FDispatch &row, dmmeta::Dispatch &out) {
    out.dispatch = row.dispatch;
    out.unk = row.unk;
    out.read = row.read;
    out.print = row.print;
    out.haslen = row.haslen;
    out.call = row.call;
    out.strict = row.strict;
    out.comment = algo::Comment(row.comment);
}

// --- doc.FDispatch.base.CopyIn
// Copy fields in to row
void doc::dispatch_CopyIn(doc::FDispatch &row, dmmeta::Dispatch &in) {
    row.dispatch = in.dispatch;
    row.unk = in.unk;
    row.read = in.read;
    row.print = in.print;
    row.haslen = in.haslen;
    row.call = in.call;
    row.strict = in.strict;
    row.comment = in.comment;
}

// --- doc.FDispatch.ns.Get
algo::strptr doc::ns_Get(doc::FDispatch& parent) {
    return algo::Pathcomp(parent.dispatch, ".RL");
}

// --- doc.FDispatch.name.Get
algo::strptr doc::name_Get(doc::FDispatch& parent) {
    return algo::Pathcomp(parent.dispatch, ".RR");
}

// --- doc.FDispatch..Init
// Set all fields to initial values.
void doc::FDispatch_Init(doc::FDispatch& parent) {
    parent.unk = bool(false);
    parent.read = bool(false);
    parent.print = bool(false);
    parent.haslen = bool(false);
    parent.call = bool(false);
    parent.strict = bool(false);
    parent.ind_dispatch_next = (doc::FDispatch*)-1; // (doc.FDb.ind_dispatch) not-in-hash
    parent.ind_dispatch_hashval = 0; // stored hash value
}

// --- doc.FDispatch..Uninit
void doc::FDispatch_Uninit(doc::FDispatch& parent) {
    ind_dispatch_Remove(parent); // remove dispatch from index ind_dispatch
}

