// --- doc.FMsg.c_msgfield.Insert
// Insert pointer to row into array. Row must not already be in array;
// no duplicate check is performed, so a duplicate insert silently appears twice.
void doc::c_msgfield_Insert(doc::FMsg& parent, doc::FMsgfield& row) {
    if (!row.msg_c_msgfield_in_ary) {
        c_msgfield_Reserve(parent, 1);
        u64 n  = parent.c_msgfield_n++;
        parent.c_msgfield_elems[n] = &row;
        row.msg_c_msgfield_in_ary = true;
    }
}

// --- doc.FMsg.c_msgfield.InsertMaybe
// Insert pointer to row in array.
// If row is already in the array, do nothing.
// Return value: whether element was inserted into array.
bool doc::c_msgfield_InsertMaybe(doc::FMsg& parent, doc::FMsgfield& row) {
    bool retval = !msg_c_msgfield_InAryQ(row);
    c_msgfield_Insert(parent,row); // check is performed in _Insert again
    return retval;
}

// --- doc.FMsg.c_msgfield.Remove
// Find element using linear scan. If element is in array, remove, otherwise do nothing
void doc::c_msgfield_Remove(doc::FMsg& parent, doc::FMsgfield& row) {
    i64 n = parent.c_msgfield_n;
    if (bool_Update(row.msg_c_msgfield_in_ary,false)) {
        doc::FMsgfield* *elems = parent.c_msgfield_elems;
        // search backward, so that most recently added element is found first.
        // if found, shift array.
        for (i64 i = n-1; i>=0; i--) {
            doc::FMsgfield* elem = elems[i]; // fetch element
            if (elem == &row) {
                i64 j = i + 1;
                size_t nbytes = sizeof(doc::FMsgfield*) * (n - j);
                memmove(elems + i, elems + j, nbytes);
                parent.c_msgfield_n = n - 1;
                break;
            }
        }
    }
}

// --- doc.FMsg.c_msgfield.Reserve
// Reserve space in index for N more elements;
void doc::c_msgfield_Reserve(doc::FMsg& parent, u64 n) {
    u64 old_max = parent.c_msgfield_max;
    if (UNLIKELY(parent.c_msgfield_n + n > old_max)) {
        u64 new_max  = u64_Max(u64_Max(old_max * 2, parent.c_msgfield_n + n), 4);
        u64 old_size = old_max * sizeof(doc::FMsgfield*);
        u64 new_size = new_max * sizeof(doc::FMsgfield*);
        void *new_mem = algo_lib::malloc_ReallocMem(parent.c_msgfield_elems, old_size, new_size);
        if (UNLIKELY(!new_mem)) {
            FatalErrorExit("doc.out_of_memory  field:doc.FMsg.c_msgfield");
        }
        parent.c_msgfield_elems = (doc::FMsgfield**)new_mem;
        parent.c_msgfield_max = new_max;
    }
}

