// --- doc.FRun.ary.Addary
// Reserve space (this may move memory). Insert N element at the end.
// Return aryptr to newly inserted block.
// If the RHS argument aliases the array (refers to the same memory), exit program with fatal error.
algo::aryptr<doc::Cell> doc::ary_Addary(doc::FRun& parent, algo::aryptr<doc::Cell> rhs) {
    bool overlaps = rhs.n_elems>0 && rhs.elems >= parent.ary_elems && rhs.elems < parent.ary_elems + parent.ary_max;
    if (UNLIKELY(overlaps)) {
        FatalErrorExit("doc.tary_alias  field:doc.FRun.ary  comment:'alias error: sub-array is being appended to the whole'");
    }
    i64 nnew = rhs.n_elems;
    ary_Reserve(parent, nnew); // reserve space
    i64 at = parent.ary_n;
    for (i64 i = 0; i < nnew; i++) {
        new (parent.ary_elems + at + i) doc::Cell(rhs[i]);
        parent.ary_n++;
    }
    return algo::aryptr<doc::Cell>(parent.ary_elems + at, nnew);
}

// --- doc.FRun.ary.Alloc
// Reserve space. Insert element at the end
// The new element is initialized to a default value
doc::Cell& doc::ary_Alloc(doc::FRun& parent) {
    ary_Reserve(parent, 1);
    i64 n  = parent.ary_n;
    i64 at = n;
    doc::Cell *elems = parent.ary_elems;
    new (elems + at) doc::Cell(); // construct new element, default initializer
    parent.ary_n = n+1;
    return elems[at];
}

// --- doc.FRun.ary.AllocAt
// Reserve space for new element, reallocating the array if necessary
// Insert new element at specified index. Index must be in range or a fatal error occurs.
doc::Cell& doc::ary_AllocAt(doc::FRun& parent, i64 at) {
    ary_Reserve(parent, 1);
    i64 n  = parent.ary_n;
    if (UNLIKELY(u64(at) >= u64(n+1))) {
        FatalErrorExit("doc.bad_alloc_at  field:doc.FRun.ary  comment:'index out of range'");
    }
    doc::Cell *elems = parent.ary_elems;
    memmove(elems + at + 1, elems + at, (n - at) * sizeof(doc::Cell));
    new (elems + at) doc::Cell(); // construct element, default initializer
    parent.ary_n = n+1;
    return elems[at];
}

// --- doc.FRun.ary.AllocN
// Reserve space. Insert N elements at the end of the array, return pointer to array
algo::aryptr<doc::Cell> doc::ary_AllocN(doc::FRun& parent, i64 n_elems) {
    ary_Reserve(parent, n_elems);
    i64 old_n  = parent.ary_n;
    i64 new_n = old_n + n_elems;
    doc::Cell *elems = parent.ary_elems;
    for (i64 i = old_n; i < new_n; i++) {
        new (elems + i) doc::Cell(); // construct new element, default initialize
    }
    parent.ary_n = new_n;
    return algo::aryptr<doc::Cell>(elems + old_n, n_elems);
}

// --- doc.FRun.ary.AllocNAt
// Reserve space. Insert N elements at the given position of the array, return pointer to inserted elements
// Reserve space for new element, reallocating the array if necessary
// Insert new element at specified index. Index must be in range or a fatal error occurs.
algo::aryptr<doc::Cell> doc::ary_AllocNAt(doc::FRun& parent, i64 n_elems, i64 at) {
    ary_Reserve(parent, n_elems);
    i64 n  = parent.ary_n;
    if (UNLIKELY(u64(at) > u64(n))) {
        FatalErrorExit("doc.bad_alloc_n_at  field:doc.FRun.ary  comment:'index out of range'");
    }
    doc::Cell *elems = parent.ary_elems;
    memmove(elems + at + n_elems, elems + at, (n - at) * sizeof(doc::Cell));
    for (i64 i = 0; i < n_elems; i++) {
        new (elems + at + i) doc::Cell(); // construct new element, default initialize
    }
    parent.ary_n = n+n_elems;
    return algo::aryptr<doc::Cell>(elems+at,n_elems);
}

// --- doc.FRun.ary.Remove
// Remove item by index. If index outside of range, do nothing.
void doc::ary_Remove(doc::FRun& parent, u64 i) {
    u64 lim = parent.ary_n;
    doc::Cell *elems = parent.ary_elems;
    if (i < lim) {
        memmove(elems + i, elems + (i + 1), sizeof(doc::Cell) * (lim - (i + 1)));
        parent.ary_n = lim - 1;
    }
}

// --- doc.FRun.ary.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void doc::ary_RemoveLast(doc::FRun& parent) {
    u64 n = parent.ary_n;
    if (n > 0) {
        n -= 1;
        parent.ary_n = n;
    }
}

// --- doc.FRun.ary.AbsReserve
// Make sure N elements fit in array. Process dies if out of memory
void doc::ary_AbsReserve(doc::FRun& parent, i64 n) {
    u64 old_max  = parent.ary_max;
    if (n > i64(old_max)) {
        u64 new_max  = i64_Max(i64_Max(old_max * 2, n), 4);
        void *new_mem = algo_lib::malloc_ReallocMem(parent.ary_elems, old_max * sizeof(doc::Cell), new_max * sizeof(doc::Cell));
        if (UNLIKELY(!new_mem)) {
            FatalErrorExit("doc.tary_nomem  field:doc.FRun.ary  comment:'out of memory'");
        }
        parent.ary_elems = (doc::Cell*)new_mem;
        parent.ary_max = new_max;
    }
}

// --- doc.FRun.ary.Setary
// Copy contents of RHS to PARENT.
void doc::ary_Setary(doc::FRun& parent, doc::FRun &rhs) {
    ary_RemoveAll(parent);
    i64 nnew = rhs.ary_n;
    ary_Reserve(parent, nnew); // reserve space
    for (i64 i = 0; i < nnew; i++) { // copy elements over
        new (parent.ary_elems + i) doc::Cell(ary_qFind(rhs, i));
        parent.ary_n = i + 1;
    }
}

// --- doc.FRun.ary.Setary2
// Copy specified array into ary, discarding previous contents.
// If the RHS argument aliases the array (refers to the same memory), throw exception.
void doc::ary_Setary(doc::FRun& parent, const algo::aryptr<doc::Cell> &rhs) {
    ary_RemoveAll(parent);
    ary_Addary(parent, rhs);
}

// --- doc.FRun.ary.AllocNVal
// Reserve space. Insert N elements at the end of the array, return pointer to array
algo::aryptr<doc::Cell> doc::ary_AllocNVal(doc::FRun& parent, i64 n_elems, const doc::Cell& val) {
    ary_Reserve(parent, n_elems);
    i64 old_n  = parent.ary_n;
    i64 new_n = old_n + n_elems;
    doc::Cell *elems = parent.ary_elems;
    for (i64 i = old_n; i < new_n; i++) {
        new (elems + i) doc::Cell(val);
    }
    parent.ary_n = new_n;
    return algo::aryptr<doc::Cell>(elems + old_n, n_elems);
}

// --- doc.FRun.ary.Insary
// Insert array at specific position
// Insert N elements at specified index. Index must be in range or a fatal error occurs.Reserve space, and move existing elements to end.If the RHS argument aliases the array (refers to the same memory), exit program with fatal error.
void doc::ary_Insary(doc::FRun& parent, algo::aryptr<doc::Cell> rhs, i64 at) {
    bool overlaps = rhs.n_elems>0 && rhs.elems >= parent.ary_elems && rhs.elems < parent.ary_elems + parent.ary_max;
    if (UNLIKELY(overlaps)) {
        FatalErrorExit("doc.tary_alias  field:doc.FRun.ary  comment:'alias error: sub-array is being appended to the whole'");
    }
    if (UNLIKELY(u64(at) >= u64(parent.ary_n+1))) {
        FatalErrorExit("doc.bad_insary  field:doc.FRun.ary  comment:'index out of range'");
    }
    i64 nnew = rhs.n_elems;
    i64 nmove = parent.ary_n - at;
    ary_Reserve(parent, nnew); // reserve space
    for (i64 i = nmove-1; i >=0 ; --i) {
        new (parent.ary_elems + at + nnew + i) doc::Cell(parent.ary_elems[at + i]);
    }
    for (i64 i = 0; i < nnew; ++i) {
        new (parent.ary_elems + at + i) doc::Cell(rhs[i]);
    }
    parent.ary_n += nnew;
}

// --- doc.FRun.ary.RemRegion
// Delete a range of elements
// Remove region from the middle of the array
// The specified region BEG..BEG+N is clipped to the valid region both from the left and from the right.
// If N is negative, nothing is removed.
void doc::ary_RemRegion(doc::FRun& parent, i64 beg, i64 n) {
    i64 end = i64_Min(beg+n, parent.ary_n);
    beg = i64_Max(beg,0);
    n = end-beg;
    if (n>0) {
        memmove(parent.ary_elems+beg, parent.ary_elems+end, sizeof(doc::Cell) * (parent.ary_n-end));
        parent.ary_n -= n;
    }
}

// --- doc.FRun.brk.Addary
// Reserve space (this may move memory). Insert N element at the end.
// Return aryptr to newly inserted block.
// If the RHS argument aliases the array (refers to the same memory), exit program with fatal error.
algo::aryptr<i32> doc::brk_Addary(doc::FRun& parent, algo::aryptr<i32> rhs) {
    bool overlaps = rhs.n_elems>0 && rhs.elems >= parent.brk_elems && rhs.elems < parent.brk_elems + parent.brk_max;
    if (UNLIKELY(overlaps)) {
        FatalErrorExit("doc.tary_alias  field:doc.FRun.brk  comment:'alias error: sub-array is being appended to the whole'");
    }
    i64 nnew = rhs.n_elems;
    brk_Reserve(parent, nnew); // reserve space
    i64 at = parent.brk_n;
    memcpy(parent.brk_elems + at, rhs.elems, nnew * sizeof(i32));
    parent.brk_n += nnew;
    return algo::aryptr<i32>(parent.brk_elems + at, nnew);
}

