// --- doc.TableId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void doc::value_SetStrptr(doc::TableId& parent, algo::strptr rhs, doc_TableIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- doc.TableId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool doc::value_ReadStrptrMaybe(doc::TableId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- doc.TableId..ReadStrptrMaybe
// Read fields of doc::TableId from an ascii string.
// The format of the string is the format of the doc::TableId's only field
bool doc::TableId_ReadStrptrMaybe(doc::TableId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

